#include <bits/stdc++.h>using namespace std;#define int long longint T,n,g,dp[5005],mx,gg[5005][5005];vector<int> d[5005]; int gcd(int a,int b){    return gg[a][b];} void init(){    for(int i=0;i<=5003;i++){        gg[i][0] = gg[0][i] = i;    }    for(int i=1;i<=5003;i++){        for(int j=1;j<=i;j++){            gg[i][j] = gg[j][i] = gg[j][i % j];        }    }} void O_o(){    mx = -1;    memset(dp,0x3f3f3f3f3f3f3f,sizeof(dp));    cin >> n;    set<int> st;    vector<int> a(n + 1);    for(int i=1;i<=n;i++){        cin >> a[i];        mx = max(mx,a[i]);        dp[a[i]] = 1;        if(i > 1){            g = gcd(g,a[i]);        }else{            g = a[i];        }    }    int cnt = 0;    for(int i=1;i<=n;i++){        if(a[i] == g){            cnt++;        }    }    if(cnt){        cout << n - cnt << '\n';        return ;    }    // dp[x] = 形成 x 的最少选取元素个数    for(int x=mx;x>=1;x--){        for(int i=1;i<=n;i++){            dp[gcd(x,a[i])] = min(dp[gcd(x,a[i])],dp[x] + 1);        }    }    cout << dp[g] + n - 2 << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    init();    cin >> T;    while(T--)O_o();    return 0;}